type Span = {
  id: string;
  parent?: string;
  kind: 'model' | 'guardrail' | 'tool' | 'http';
  expected?: string;
  actual?: string;
};

// spans are appended by the runtime when a span finishes, not when it starts
function firstDivergence(spans: Span[]) {
  return spans.find((s) => s.expected !== undefined && s.expected !== s.actual);
}

const spans: Span[] = [
  { id: 's1', kind: 'model', expected: 'call refunds_create', actual: 'call refunds_create' },
  { id: 's3', parent: 's1', kind: 'tool', expected: 'refund 420', actual: 'refund 4200' },
  { id: 's2', parent: 's1', kind: 'guardrail', expected: 'amount <= 500', actual: 'amount <= 50000' },
  { id: 's4', parent: 's2', kind: 'http', expected: 'policy v3', actual: 'policy v3' },
];

const bad = firstDivergence(spans);
analytics.write({ span: bad?.id, payload: bad?.actual });
